INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 10, 'theory', 'Quiz: trees and traversals');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 0, 'A complete binary tree is stored in an array, with the root at position 0. Where are the children of the node at position 5?', '["Positions 6 and 7", "Positions 10 and 11", "Positions 11 and 12", "Positions 9 and 10"]', 2, 'The children of node i are at positions 2i + 1 and 2i + 2: for i = 5 that is 11 and 12. This is why the heap needs no links.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 1, 'Which depth-first traversal lists the values of a binary search tree in ascending order?', '["Preorder (node, left, right)", "Inorder (left, node, right)", "Postorder (left, right, node)", "Breadth-first traversal"]', 1, 'The search tree rule is smaller values on the left, larger on the right: inorder visits the left subtree, then the node, then the right subtree, which gives everything in ascending order.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 2, 'Why are traversals of very deep trees written with an explicit stack rather than recursion?', '["An explicit stack is always faster", "Recursion uses the call stack, whose depth equals the tree height, so it overflows on a chain", "Recursion cannot traverse the right subtree", "An explicit stack uses less memory on any tree"]', 1, 'A degenerate tree of a hundred thousand nodes is a chain of height a hundred thousand; a recursive traversal will crash, while an explicit stack lives in ordinary memory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 3, 'Which data structure does breadth-first traversal need?', '["Stack", "Queue", "Hash table", "Heap"]', 1, 'A queue puts children at the tail and takes nodes from the head, level after level. Replace the queue with a stack and you get depth-first traversal.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 10, 4, 'How is the diameter of a tree computed in a single traversal?', '["A separate traversal is run for every node", "The function returns the subtree height and along the way updates the maximum of the sum of the left and right heights", "The nodes are sorted by depth", "Take twice the tree height"]', 1, 'A path through a node as its top point has length left height plus right height. The subtree returns its height upward, while the best sum is remembered separately.');
